const REQUEST_NOTE='Valores e pagamento são combinados entre vocês. O Bivaque não intermedeia pagamento nem garante o serviço.';
function requestRow(r){const st=requestStatus(r),n=requestLiveProposals(r).length;return `<button type="button" class="list-row" data-action="open-request" data-value="${r.id}">${icon('build')}<span class="txt grow"><b>${esc(r.cat)} · ${esc(r.hood)}</b><small>${esc(requestStatusLabel(r))}${r.mine&&st!=='cancelled'?` · ${n} proposta${n===1?'':'s'}`:''}</small></span>${icon('chevron_right')}</button>`;}
function renderRequests(){
 const mine=requestList().filter(r=>r.mine).sort((a,b)=>b.createdAt-a.createdAt),forMe=providerRequests();
 return `<div class="page-head"><div><h1>Pedidos de serviço</h1><p>Descreva o que precisa e receba até ${REQUEST_LIMIT} propostas de empresas do ramo em ${esc(state.homeCity)}.</p><p class="form-note">${REQUEST_NOTE}</p></div>${!readonly()?btn('Contratar serviço','create-request','','filled','build'):''}</div>${readonlyHtml()}
 <section class="section">${sectionTitle('Meus pedidos')}${mine.length?`<div class="list">${mine.map(requestRow).join('')}</div>`:empty('Nenhum pedido ainda','Conte o serviço, o bairro e quando precisa. Empresas do ramo respondem com valor, data e prazo.','build')}</section>
 ${state.myBiz?.live?`<section class="section">${sectionTitle(`Pedidos para ${state.myBiz.name}`)}${forMe.length?`<div class="list">${forMe.map(requestRow).join('')}</div>`:empty('Nenhum pedido no seu ramo agora',`Pedidos de ${state.myBiz.cat} em ${state.myBiz.city} que atendem seus bairros aparecem aqui.`,'inbox')}</section>`:''}`;
}
function proposalCard(r,p,{showChoose,mineView}){const b=bizById(p.bizId)||(state.myBiz?.id===p.bizId?state.myBiz:null);const chosen=r.chosen===p.id;return `<article class="photo-card" style="padding:16px;display:grid;gap:8px${chosen?';border-color:var(--md-sys-color-primary)':''}"><div class="row between"><b>${esc(b?.name||'Empresa')}</b>${chosen?pill('Escolhida','ok','check_circle'):p.status==='declined'?pill('Não escolhida'):''}</div><p style="font-size:22px;font-weight:600;margin:0">${esc(proposalPrice(p))}</p><p class="small muted" style="margin:0">Disponível em ${esc(dateLabel(p.date))} · Execução: ${esc(p.duration)} · Válida até ${esc(dateLabel(p.validUntil))}</p>${p.msg?`<p class="small" style="margin:0">${esc(p.msg)}</p>`:''}<div class="row" style="gap:8px;flex-wrap:wrap">${showChoose?btn('Escolher esta proposta','choose-proposal',`${r.id}|${p.id}`,'filled','check'):''}${chosen&&r.threadId?btn('Abrir conversa','open-thread',r.threadId,'tonal','chat_bubble'):''}${mineView&&requestActive(r)?btn('Editar proposta','propose',r.id,'outlined','edit')+btn('Retirar','withdraw-proposal',r.id,'text','undo'):''}${b&&!mineView?btn('Ver empresa','open-biz',b.id,'text','storefront'):''}${mineView?'':btn('Denunciar','report',`proposal|${p.id}`,'text','flag')}</div></article>`;}
function renderRequest(){
 const r=requestById(route.id);if(!r||(!r.mine&&!providerCanSee(r)))return unavailable();const details=r.mine||providerSeesDetails(r);
 const st=requestStatus(r),live=requestLiveProposals(r),active=requestActive(r);
 const head=`<div class="detail-title"><span>${pill(requestStatusLabel(r),st==='chosen'?'ok':st==='cancelled'||st==='expired'?'warn':'')}</span><h1>${esc(r.cat)}</h1><p class="muted">${esc(r.hood)} · ${esc(requestWhenLabel(r))}${r.mine||!details?'':` · Pedido de ${esc(r.who)}`}</p></div>${details?`<p class="detail-copy">${esc(r.desc)}</p>`:'<p class="small muted">Este pedido foi encerrado. Os detalhes ficam visíveis só para a empresa escolhida.</p>'}${details&&r.photos.length?`<div class="photo-previews">${r.photos.map(src=>`<img src="${esc(src)}" alt="Foto do pedido" style="width:96px;height:96px;object-fit:cover;border-radius:12px">`).join('')}</div>`:''}<p class="form-note">${REQUEST_NOTE}</p>`;
 if(r.mine){const eligible=requestEligible(r).length;const list=st==='chosen'?[...live].sort((a,b)=>(b.id===r.chosen)-(a.id===r.chosen)):live;return `${head}<section class="section">${sectionTitle(`Propostas (${live.length} de ${REQUEST_LIMIT})`)}${active&&!live.length?`<p class="small muted">Enviado para ${eligible} empresa${eligible===1?'':'s'} de ${esc(r.cat)} em ${esc(r.city)}. Expira em ${esc(dateLabel(new Date(r.expiresAt).toISOString().slice(0,10)))}.</p>`:''}<div class="stack">${list.map(p=>proposalCard(r,p,{showChoose:active})).join('')||empty(active?'Aguardando propostas':'Nenhuma proposta recebida',active?'As empresas do ramo podem responder em até 7 dias.':'Este pedido não recebeu propostas.','request_quote')}</div></section>${active?`<section class="section">${btn('Cancelar pedido','cancel-request',r.id,'outlined','close').replace('<md-outlined-button','<md-outlined-button class="danger"')}</section>`:''}`;}
 const mineP=myProposal(r);
 return `${head}<section class="section">${sectionTitle('Sua proposta')}${mineP?proposalCard(r,mineP,{mineView:true}):r.chosen?'<p class="small muted">O cliente já escolheu uma proposta.</p>':!active?'<p class="small muted">Este pedido não recebe mais propostas.</p>':requestFull(r)?`<p class="small muted">Este pedido já recebeu ${REQUEST_LIMIT} propostas.</p>`:`<p class="small muted">Você não vê as propostas de outras empresas.</p>${btn('Enviar proposta','propose',r.id,'filled','request_quote')}`}</section>${details?`<section class="section">${btn('Denunciar pedido','report',`request|${r.id}`,'text','flag')}</section>`:''}`;
}
function openRequestEditor(){if(!canPost())return;if(requestList().filter(r=>r.mine&&requestActive(r)).length>=REQUEST_OPEN_MAX){notify(`Você já tem ${REQUEST_OPEN_MAX} pedidos abertos. Encerre ou cancele um antes.`,'info');return;}editor={kind:'request',photos:[],maxPhotos:REQUEST_PHOTOS};editorDirty=false;showDialog('Contratar serviço',`<p class="form-note">Seu pedido vai para as empresas do ramo em ${esc(state.homeCity)}. Até ${REQUEST_LIMIT} podem enviar proposta com valor, data e prazo.</p><div class="form-grid">${selectField('request-cat','Tipo de serviço',[['','Escolher'],...CAT_NAMES.slice(1)],'','required class="full"')}${selectField('request-hood','Bairro',HOODS,'','required class="full"')}${field('request-desc','O que você precisa','','type="textarea" rows="4" required minlength="20" maxlength="1000" supporting-text="Detalhe o serviço. Não informe endereço, documentos ou telefone." class="full"')}${selectField('request-when','Quando',[['asap','O quanto antes'],['until','Até uma data'],['on','Em uma data específica']],'asap','class="full"')}<label class="field-label full" id="request-date-wrap" style="display:none">Data<input type="date" id="request-date" min="${dateISO()}" value="${dateISO(3)}"></label></div>${photoUploadHtml(REQUEST_PHOTOS)}<p class="form-note">Fotos ajudam no orçamento. Evite pessoas, documentos e o número da casa. Só as empresas do ramo veem.</p><p class="form-note">${REQUEST_NOTE}</p>`,`${btn('Cancelar','close-dialog','','text')}${btn('Enviar pedido','submit-request','','filled','send')}`,'editor');$('#request-when')?.addEventListener('change',e=>{$('#request-date-wrap').style.display=e.target.value==='asap'?'none':'';});}
function openProposalEditor(rid){const r=requestById(rid);if(!r||!state.myBiz?.live||!requestActive(r))return;const p=myProposal(r);if(!p&&requestFull(r)){notify(`Este pedido já recebeu ${REQUEST_LIMIT} propostas.`,'info');return;}editor={kind:'proposal',id:rid,photos:[]};editorDirty=false;const kind=p?.price.kind||'fixed';showDialog(p?'Editar proposta':'Enviar proposta',`<p class="form-note">${esc(r.cat)} · ${esc(r.hood)} · ${esc(requestWhenLabel(r))}</p><div class="form-grid">${selectField('prop-kind','Valor',[['fixed','Valor fixo'],['range','Faixa de valor'],['visit','A combinar após visita']],kind,'class="full"')}<div data-price="fixed">${field('prop-value','Valor (R$)',p?.price.kind==='fixed'?p.price.min:'','type="number" min="1" max="1000000"')}</div><div data-price="range">${field('prop-min','De (R$)',p?.price.kind==='range'?p.price.min:'','type="number" min="1" max="1000000"')}</div><div data-price="range">${field('prop-max','Até (R$)',p?.price.kind==='range'?p.price.max:'','type="number" min="1" max="1000000"')}</div><label class="field-label">Disponível a partir de<input type="date" id="prop-date" min="${dateISO()}" value="${p?.date||dateISO(2)}"></label><label class="field-label">Proposta válida até<input type="date" id="prop-valid" min="${dateISO()}" value="${p?.validUntil||dateISO(7)}"></label>${field('prop-duration','Prazo de execução',p?.duration||'','required maxlength="40" supporting-text="Ex.: 1 dia, 2 a 3 dias" class="full"')}${field('prop-msg','Mensagem para o cliente',p?.msg||'','type="textarea" rows="3" required minlength="10" maxlength="400" class="full"')}</div><p class="form-note">${REQUEST_NOTE}</p>`,`${btn('Cancelar','close-dialog','','text')}${btn(p?'Salvar proposta':'Enviar proposta','submit-proposal',rid,'filled','send')}`,'editor');const toggle=v=>{for(const el of dialog.querySelectorAll('[data-price]'))el.style.display=el.dataset.price===v?'':'none';};toggle(kind);$('#prop-kind')?.addEventListener('change',e=>toggle(e.target.value));}
